def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    current = chain_dict['pjb']
    result = []
    while current:
        result.append(current)
        next_a = chain_dict.get(current[0], [])
        next_b = chain_dict.get(current[1], [])
        if next_a:
            current = next_a[0]
        else:
            current = next_b[0]

    return ','.join(result)
